Here is a compact, fully‑featured **pytest** test suite for `deep_get`.  
All tests are self‑contained, cover **happy‑path**, **edge‑case** and **error‑case** scenarios, and follow the usual `test_` naming convention.

```python
# test_deep_get.py
import pytest
from deep_get import deep_get          # adjust the import to match your project layout


# ----------------------------------------------------------------------
# Helper / Fixtures
# ----------------------------------------------------------------------
@pytest.fixture
def sample_nested():
    """A small nested dictionary used across several tests."""
    return {
        "a": {
            "b": {
                "c": 42
            },
            "d": ["list_item"],
            "e": None,
        },
        "x": {
            "y": {
                "z": "deep string"
            }
        },
    }


# ----------------------------------------------------------------------
# Happy‑path tests
# ----------------------------------------------------------------------
class TestDeepGetHappyPath:
    """Basic usage – keys that exist at various depths."""

    def test_top_level_key(self, sample_nested):
        assert deep_get(sample_nested, "a") == sample_nested["a"]

    def test_one_level_key(self, sample_nested):
        assert deep_get(sample_nested, "a.b") == sample_nested["a"]["b"]

    def test_two_level_key(self, sample_nested):
        assert deep_get(sample_nested, "a.b.c") == 42

    def test_last_level_string(self, sample_nested):
        assert deep_get(sample_nested, "x.y.z") == "deep string"

    def test_missing_key_returns_default_none(self, sample_nested):
        assert deep_get(sample_nested, "nonexistent") is None

    def test_missing_key_returns_custom_default(self, sample_nested):
        assert deep_get(sample_nested, "a.missing", default=-1) == -1

    def test_custom_default_on_top_level(self):
        d = {}
        sentinel = object()
        assert deep_get(d, "any", default=sentinel) is sentinel

    def test_value_can_be_none(self, sample_nested):
        """A key that exists but holds `None` must be returned, not the default."""
        assert deep_get(sample_nested, "a.e") is None

    def test_existing_path_with_default_none(self):
        d = {"foo": {"bar": None}}
        assert deep_get(d, "foo.bar", default="fallback") is None

    @pytest.mark.parametrize(
        "key_path, expected",
        [
            ("a", {"b": {"c": 42}, "d": ["list_item"], "e": None}),
            ("a.b", {"c": 42}),
            ("a.b.c", 42),
            ("x.y.z", "deep string"),
        ],
    )
    def test_parametrized_existing_paths(self, sample_nested, key_path, expected):
        assert deep_get(sample_nested, key_path) == expected


# ----------------------------------------------------------------------
# Edge‑case tests
# ----------------------------------------------------------------------
class TestDeepGetEdgeCases:
    """Situations that are legal but a bit unusual."""

    def test_empty_key_string(self):
        """'' splits to [''] → first lookup on '' key → default."""
        d = {"a": 1}
        assert deep_get(d, "", default="EMPTY") == "EMPTY"

    def test_leading_dot(self):
        """Key starts with a dot → split yields '' then the real key."""
        d = {"a": 1}
        assert deep_get(d, ".a", default="LEAD") == "LEAD"

    def test_trailing_dot(self):
        """Key ends with a dot → split yields real keys then ''."""
        d = {"a": {"b": 1}}
        assert deep_get(d, "a.b.", default="TRAIL") == "TRAIL"

    def test_multiple_consecutive_dots(self):
        """'a..b' → split yields ['a', '', 'b']"""
        d = {"a": {"b": 2}}
        assert deep_get(d, "a..b", default="MULTIDOT") == "MULTIDOT"

    def test_only_dots(self):
        """'.' → split yields ['', '']"""
        d = {}
        assert deep_get(d, ".", default="ONLY_DOTS") == "ONLY_DOTS"

    def test_intermediate_non_dict(self):
        """A key points to a non‑dict, so further navigation should bail out."""
        d = {"a": "not_a_dict"}
        assert deep_get(d, "a.b.c", default="INTERMEDIATE") == "INTERMEDIATE"

    def test_intermediate_none(self):
        """An intermediate value is None → cannot descend further."""
        d = {"a": None}
        assert deep_get(d, "a.b", default="NONE_INTER") == "NONE_INTER"

    def test_deeply_nested(self):
        """A very deep hierarchy (20 levels) works correctly."""
        nested = {}
        cur = nested
        for i in range(20):
            cur[f"l{i}"] = {} if i < 19 else "deep"
            cur = cur[f"l{i}"]
        path = ".".join([f"l{i}" for i in range(20)])
        assert deep_get(nested, path) == "deep"

    def test_numeric_string_keys(self):
        """Dictionary keys that look like numbers but are strings."""
        d = {"1": {"2": "numeric"}}
        assert deep_get(d, "1.2") == "numeric"

    def test_whitespace_in_key_path(self):
        """Keys contain spaces – they are treated literally."""
        d = {" a ": {" b ": 1}}
        assert deep_get(d, " a . b ", default="NO") == 1

    def test_unicode_keys(self):
        d = {"α": {"β": "unicode"}}
        assert deep_get(d, "α.β") == "unicode"

    def test_missing_key_deep_in_existing_branch(self):
        """Part of the path exists, but the final key does not."""
        d = {"a": {"b": {}}}
        assert deep_get(d, "a.b.c", default="MISSING") == "MISSING"

    def test_empty_dict(self):
        d = {}
        assert deep_get(d, "any", default=123) == 123

    def test_default_mutable_not_mutated(self):
        """Passing a mutable default (e.g. list) must not be altered."""
        d = {"a": {"b": [1, 2]}}
        default_list = [0]
        result = deep_get(d, "a.c", default=default_list)
        assert result == [0]
        assert default_list == [0]               # unchanged


# ----------------------------------------------------------------------
# Error‑case tests
# ----------------------------------------------------------------------
class TestDeepGetErrors:
    """Inputs that are illegal for the function – usually raise errors."""

    def test_non_dict_first_argument_returns_default(self):
        """If the first argument is not a dict, the function safely returns default."""
        assert deep_get("string", "a.b", default="FALLBACK") == "FALLBACK"
        assert deep_get(42, "a", default="FALLBACK") == "FALLBACK"
        assert deep_get(None, "a", default="FALLBACK") == "FALLBACK"
        # No exception should be raised
        assert True

    def test_keys_must_be_string(self):
        """Passing a non‑string `keys` argument should raise AttributeError."""
        with pytest.raises(AttributeError, match="'int' object has no attribute 'split'"):
            deep_get({"a": 1}, 123)          # 123 has no .split()

    def test_keys_argument_none_raises(self):
        """Passing `None` as keys also fails on `.split()`."""
        with pytest.raises(AttributeError):
            deep_get({"a": 1}, None)

    def test_special_float_keys_cause_type_error(self):
        """Float keys are strings in the path – they are searched as strings."""
        d = {1.5: {"key": "value"}}           # numeric keys won't match string '1.5'
        assert deep_get(d, "1.5.key", default="MISSING") == "MISSING"
        # No exception – the function gracefully returns the default.

    def test_unhashable_dict_key(self):
        """If a dict contains an unhashable key, it’s still a dict; the function works."""
        d = {[1, 2]: "list_as_key"}          # Python dicts can have list keys (unhashable)
        # The function will try to look up '[1, 2]' which is unhashable and raises TypeError.
        # This is considered an error case – the caller must avoid such dicts.
        with pytest.raises(TypeError):
            deep_get(d, "[1, 2]")


# ----------------------------------------------------------------------
# Optional: quick sanity test when run as a script
# ----------------------------------------------------------------------
if __name__ == "__main__":
    pytest.main([__file__, "-v"])
```

### How the tests are organized

| Section | What it covers |
|--------|----------------|
| **Happy‑path** | Keys that exist at the top level, one level down, several levels deep; returns the actual value; custom default; returning `None` when the stored value is `None`. |
| **Edge‑cases** | Empty/blank key strings, leading/trailing/multiple dots, non‑dict intermediate values, `None` intermediates, very deep nesting, numeric/unicode/whitespace keys, mutable defaults not being mutated, missing keys in a partially‑existing branch. |
| **Error‑cases** | Passing non‑dict as the first argument (returns default), passing a non‑string `keys` (raises `AttributeError`), passing `None` as keys, float keys, and using unhashable keys in the dictionary (raises `TypeError`). |

The test file can be run with:

```bash
pytest test_deep_get.py -v
```

Feel free to tweak the fixtures or add more `parametrize` rows to suit the exact contract you expect from `deep_get`. Happy testing!
